#import <Foundation/Foundation.h>
#import <UIKit/UIKit.h>
#import <ReplayKit/ReplayKit.h>
#import <AVKit/AVKit.h>
#import <AVFoundation/AVFoundation.h>
#import <math.h>
#import <Photos/Photos.h>
#import <QuartzCore/QuartzCore.h>

// ReplayKit's ordinary in-app recording API. No private hooks, networking or background capture.
@interface CRController : NSObject <RPScreenRecorderDelegate>
@property(nonatomic,strong) NSTimer *timer;
@property(nonatomic,strong) UILabel *indicator;
@property(nonatomic,copy) NSString *state;
@property(nonatomic,copy) NSString *detail;
@property(nonatomic,copy) NSString *lastCommand;
@property(nonatomic,strong) NSDate *startDate;
@property(nonatomic) BOOL ownsRecording;
@property(nonatomic,weak) id<RPScreenRecorderDelegate> previousDelegate;
@property(nonatomic) BOOL stopWhenStarted;
- (void)stop;
@end
static CRController *controller;
static NSUserDefaults *prefs(void){return NSUserDefaults.standardUserDefaults;}
static NSURL *directory(void){return [[NSFileManager.defaultManager URLsForDirectory:NSDocumentDirectory inDomains:NSUserDomainMask].firstObject URLByAppendingPathComponent:@"CordRecorder" isDirectory:YES];}
static UIWindow *window(void){for(UIScene *s in UIApplication.sharedApplication.connectedScenes){if(s.activationState!=UISceneActivationStateForegroundActive||![s isKindOfClass:UIWindowScene.class])continue;for(UIWindow *w in ((UIWindowScene*)s).windows)if(w.isKeyWindow)return w;}return nil;}
static UIViewController *presenter(void){UIViewController *v=window().rootViewController;while(v.presentedViewController&&!v.presentedViewController.isBeingDismissed)v=v.presentedViewController;return v;}
static NSURL *movie(NSString *name){if(![name isKindOfClass:NSString.class]||![name.pathExtension.lowercaseString isEqualToString:@"mp4"]||![name.lastPathComponent isEqualToString:name]||![name hasPrefix:@"Recording-"])return nil;NSURL *u=[directory() URLByAppendingPathComponent:name];return [NSFileManager.defaultManager fileExistsAtPath:u.path]?u:nil;}
@implementation CRController
- (void)publish:(NSString*)state detail:(NSString*)detail {self.state=state;self.detail=detail?:@"";[prefs() setObject:state forKey:@"CRState"];[prefs() setObject:self.detail forKey:@"CRDetail"];[prefs() setInteger:1 forKey:@"CRVersion"];}
- (void)library {NSMutableArray *rows=[NSMutableArray array];NSArray *items=[NSFileManager.defaultManager contentsOfDirectoryAtURL:directory() includingPropertiesForKeys:@[NSURLFileSizeKey,NSURLCreationDateKey] options:NSDirectoryEnumerationSkipsHiddenFiles error:nil];for(NSURL *url in items){if(!movie(url.lastPathComponent))continue;NSNumber *size=nil;NSDate *date=nil;[url getResourceValue:&size forKey:NSURLFileSizeKey error:nil];[url getResourceValue:&date forKey:NSURLCreationDateKey error:nil];[rows addObject:@{@"name":url.lastPathComponent,@"bytes":size?:@0,@"date":@((date?:NSDate.date).timeIntervalSince1970*1000)}];}[rows sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [b[@"date"] compare:a[@"date"]];}];NSData *json=[NSJSONSerialization dataWithJSONObject:rows options:0 error:nil];if(json)[prefs() setObject:[[NSString alloc]initWithData:json encoding:NSUTF8StringEncoding] forKey:@"CRLibrary"];}
- (void)updateIndicator {BOOL showing=self.ownsRecording&&([self.state isEqualToString:@"recording"]||[self.state isEqualToString:@"saving"]);if(!showing){[self.indicator removeFromSuperview];self.indicator=nil;return;}UIWindow *w=window();if(!w)return;if(!self.indicator||self.indicator.superview!=w){[self.indicator removeFromSuperview];UILabel *l=[UILabel new];l.backgroundColor=[UIColor colorWithRed:.78 green:.09 blue:.14 alpha:.96];l.textColor=UIColor.whiteColor;l.font=[UIFont monospacedDigitSystemFontOfSize:12 weight:UIFontWeightBold];l.textAlignment=NSTextAlignmentCenter;l.layer.cornerRadius=9;l.clipsToBounds=YES;l.userInteractionEnabled=NO;l.accessibilityLabel=@"Screen recording active";[w addSubview:l];self.indicator=l;}[w bringSubviewToFront:self.indicator];self.indicator.frame=CGRectMake((w.bounds.size.width-110)/2,MAX(w.safeAreaInsets.top,12),110,22);NSInteger seconds=MAX(0,(NSInteger)-[self.startDate timeIntervalSinceNow]);self.indicator.text=[NSString stringWithFormat:@"● REC %02ld:%02ld",(long)(seconds/60),(long)(seconds%60)];}
- (void)startWithMic:(BOOL)mic {if(![self.state isEqualToString:@"idle"])return;RPScreenRecorder *r=RPScreenRecorder.sharedRecorder;UIViewController *v=presenter();if(!v||!r.available||r.recording){[self publish:@"idle" detail:@"ReplayKit unavailable or another recording is active."];return;}[self publish:@"confirming" detail:@"Confirm recording permission."];UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Start CordRecorder?" message:@"This records Discord’s screen and supported audio. Only record calls after everyone agrees. Recording is saved on this device. iOS may request permission." preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:^(__unused UIAlertAction *action){[self publish:@"idle" detail:@"Recording canceled."];}]];[a addAction:[UIAlertAction actionWithTitle:@"Everyone agrees — Record" style:UIAlertActionStyleDefault handler:^(__unused UIAlertAction *action){if(UIApplication.sharedApplication.applicationState!=UIApplicationStateActive||!r.available||r.recording){[self publish:@"idle" detail:@"Recording no longer available."];return;}self.stopWhenStarted=NO;[self publish:@"starting" detail:@"Waiting for ReplayKit…"];self.previousDelegate=r.delegate;r.delegate=self;r.microphoneEnabled=mic;[r startRecordingWithHandler:^(NSError *error){dispatch_async(dispatch_get_main_queue(), ^{if(error){self.ownsRecording=NO;if(RPScreenRecorder.sharedRecorder.delegate==self)RPScreenRecorder.sharedRecorder.delegate=self.previousDelegate;[self publish:@"idle" detail:error.localizedDescription];return;}self.ownsRecording=YES;self.startDate=NSDate.date;[self publish:@"recording" detail:@"Recording Discord. Call audio support is not yet verified."];[self updateIndicator];if(self.stopWhenStarted||UIApplication.sharedApplication.applicationState==UIApplicationStateBackground)[self stop];});}];}]];[v presentViewController:a animated:YES completion:nil];}
- (void)stop {if([self.state isEqualToString:@"starting"]){self.stopWhenStarted=YES;return;}if(!self.ownsRecording||![self.state isEqualToString:@"recording"])return;[self publish:@"saving" detail:@"Finalizing recording…"];NSError *error=nil;NSURL *dir=directory();if(![NSFileManager.defaultManager createDirectoryAtURL:dir withIntermediateDirectories:YES attributes:nil error:&error]){[RPScreenRecorder.sharedRecorder stopRecordingWithHandler:^(__unused RPPreviewViewController *p,__unused NSError *e){dispatch_async(dispatch_get_main_queue(),^{self.ownsRecording=NO;if(RPScreenRecorder.sharedRecorder.delegate==self)RPScreenRecorder.sharedRecorder.delegate=self.previousDelegate;[self publish:@"idle" detail:@"Cannot create recording folder."];[self updateIndicator];});}];return;}NSString *idstr=NSUUID.UUID.UUIDString;NSURL *tmp=[dir URLByAppendingPathComponent:[NSString stringWithFormat:@".pending-%@.mp4",idstr]];NSURL *dst=[dir URLByAppendingPathComponent:[NSString stringWithFormat:@"Recording-%@.mp4",idstr]];[RPScreenRecorder.sharedRecorder stopRecordingWithOutputURL:tmp completionHandler:^(NSError *e){dispatch_async(dispatch_get_main_queue(),^{self.ownsRecording=NO;if(RPScreenRecorder.sharedRecorder.delegate==self)RPScreenRecorder.sharedRecorder.delegate=self.previousDelegate;[self updateIndicator];NSError *moveError=nil;if(e||![NSFileManager.defaultManager moveItemAtURL:tmp toURL:dst error:&moveError]){[NSFileManager.defaultManager removeItemAtURL:tmp error:nil];[self publish:@"idle" detail:(e?:moveError).localizedDescription?:@"Could not save video."];return;}[self library];[self publish:@"idle" detail:@"Recording saved. Open plugin settings to play or export it."];});}];}
- (void)openMovie:(NSString*)name action:(NSString*)action {NSURL *u=movie(name);UIViewController *v=presenter();if(!u||!v){[self publish:@"idle" detail:@"Recording not found or UI unavailable."];return;}if([action isEqualToString:@"photos"]){if(![NSBundle.mainBundle objectForInfoDictionaryKey:@"NSPhotoLibraryAddUsageDescription"]){[self publish:@"idle" detail:@"Photos permission description missing. Use Share / Save to Files instead."];return;}[self publish:@"exporting" detail:@"Saving to Photos…"];[PHPhotoLibrary requestAuthorizationForAccessLevel:PHAccessLevelAddOnly handler:^(PHAuthorizationStatus auth){if(auth!=PHAuthorizationStatusAuthorized&&auth!=PHAuthorizationStatusLimited){dispatch_async(dispatch_get_main_queue(),^{[self publish:@"idle" detail:@"Photos access denied. Local video retained."];});return;}[PHPhotoLibrary.sharedPhotoLibrary performChanges:^{[PHAssetChangeRequest creationRequestForAssetFromVideoAtFileURL:u];} completionHandler:^(BOOL success,NSError *err){dispatch_async(dispatch_get_main_queue(),^{[self publish:@"idle" detail:success?@"Saved to Photos. Local copy retained.":err.localizedDescription?:@"Could not save to Photos."];});}];}];}else if([action isEqualToString:@"play"]){AVPlayerViewController *p=[AVPlayerViewController new];p.player=[AVPlayer playerWithURL:u];[v presentViewController:p animated:YES completion:^{[p.player play];}];}else if([action isEqualToString:@"share"]){UIActivityViewController *a=[[UIActivityViewController alloc]initWithActivityItems:@[u] applicationActivities:nil];a.popoverPresentationController.sourceView=v.view;a.popoverPresentationController.sourceRect=CGRectMake(CGRectGetMidX(v.view.bounds),CGRectGetMidY(v.view.bounds),1,1);[v presentViewController:a animated:YES completion:nil];}else if([action isEqualToString:@"delete"]){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Delete recording?" message:@"This removes the local copy." preferredStyle:UIAlertControllerStyleAlert];[a addAction:[UIAlertAction actionWithTitle:@"Cancel" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"Delete" style:UIAlertActionStyleDestructive handler:^(__unused UIAlertAction *x){NSError *e=nil;[NSFileManager.defaultManager removeItemAtURL:u error:&e];[self library];[self publish:@"idle" detail:e.localizedDescription?:@"Recording deleted."];}]];[v presentViewController:a animated:YES completion:nil];}else if([action isEqualToString:@"inspect"]){AVURLAsset *asset=[AVURLAsset URLAssetWithURL:u options:nil];[asset loadValuesAsynchronouslyForKeys:@[@"tracks",@"duration"] completionHandler:^{NSError *e=nil;BOOL ok=[asset statusOfValueForKey:@"tracks" error:&e]==AVKeyValueStatusLoaded;NSUInteger audio=ok?[asset tracksWithMediaType:AVMediaTypeAudio].count:0;NSUInteger video=ok?[asset tracksWithMediaType:AVMediaTypeVideo].count:0;double seconds=CMTimeGetSeconds(asset.duration);dispatch_async(dispatch_get_main_queue(),^{if([self.state isEqualToString:@"idle"])[self publish:@"idle" detail:ok?[NSString stringWithFormat:@"Video tracks: %lu · Audio tracks: %lu · %.1f s. Audio tracks do not prove that both sides of a call are audible.",(unsigned long)video,(unsigned long)audio,isfinite(seconds)?seconds:0]:e.localizedDescription?:@"Could not inspect tracks."];});}];}}
- (void)tick {if(self.ownsRecording)[self updateIndicator];NSString *raw=[prefs() stringForKey:@"CRCommand"];if(!raw.length||[raw isEqualToString:self.lastCommand])return;self.lastCommand=raw;NSData *data=[raw dataUsingEncoding:NSUTF8StringEncoding];id parsed=[NSJSONSerialization JSONObjectWithData:data options:0 error:nil];if(![parsed isKindOfClass:NSDictionary.class])return;NSDictionary *c=parsed;NSString *action=c[@"action"];if(![c[@"at"] isKindOfClass:NSNumber.class]||fabs(NSDate.date.timeIntervalSince1970*1000-[c[@"at"] doubleValue])>15000)return;if(![action isKindOfClass:NSString.class])return;[prefs() setObject:c[@"id"]?:@"" forKey:@"CRAck"];if([action isEqualToString:@"stop"]){[self stop];return;}if([action isEqualToString:@"refresh"]){[self library];return;}if(UIApplication.sharedApplication.applicationState!=UIApplicationStateActive||![self.state isEqualToString:@"idle"])return;if([action isEqualToString:@"start"])[self startWithMic:[c[@"mic"] boolValue]];else [self openMovie:c[@"name"] action:action];}
- (void)background:(__unused NSNotification*)n {if(self.ownsRecording||[self.state isEqualToString:@"starting"])[self stop];}
- (void)screenRecorder:(RPScreenRecorder*)r didStopRecordingWithPreviewViewController:(RPPreviewViewController*)preview error:(NSError*)error {dispatch_async(dispatch_get_main_queue(),^{if(!self.ownsRecording||[self.state isEqualToString:@"saving"])return;self.ownsRecording=NO;if(RPScreenRecorder.sharedRecorder.delegate==self)RPScreenRecorder.sharedRecorder.delegate=self.previousDelegate;[self updateIndicator];[self publish:@"idle" detail:error.localizedDescription?:@"Recording interrupted. Use Stop before leaving Discord to save to the library."];UIViewController *v=presenter();if(preview&&v){[v presentViewController:preview animated:YES completion:nil];}});}
- (void)screenRecorder:(RPScreenRecorder*)r didStopRecordingWithError:(NSError*)error previewViewController:(RPPreviewViewController*)preview {[self screenRecorder:r didStopRecordingWithPreviewViewController:preview error:error];}
@end
__attribute__((constructor)) static void initializeCordRecorder(void){@autoreleasepool{NSString *previous=[prefs() stringForKey:@"CRCommand"];[prefs() setInteger:0 forKey:@"CRVersion"];[prefs() setObject:@"" forKey:@"CRAck"];dispatch_async(dispatch_get_main_queue(), ^{controller=[CRController new];controller.lastCommand=previous;[controller publish:@"idle" detail:@"Native recorder ready. No recording started."];[controller library];[NSNotificationCenter.defaultCenter addObserver:controller selector:@selector(background:) name:UIApplicationDidEnterBackgroundNotification object:nil];controller.timer=[NSTimer scheduledTimerWithTimeInterval:.25 target:controller selector:@selector(tick) userInfo:nil repeats:YES];});}}
